from pathlib import Path
import json, re

ROOT=Path(__file__).resolve().parents[1]

def read(name): return (ROOT/name).read_text()
def write(name,text): (ROOT/name).write_text(text)
def must_replace(text, old, new, label):
    if old not in text:
        raise SystemExit(f'patch anchor missing: {label}')
    return text.replace(old,new,1)

app=read('app.js')
app=re.sub(r"APP_VERSION='0\.9\.3'", "APP_VERSION='0.9.4'", app, count=1)
if "APP_VERSION='0.9.4'" not in app: raise SystemExit('APP_VERSION patch failed')

old="function rememberCoach(c,t){promiseState();if(!universe.coachArchive.some(x=>x.id===c.id))universe.coachArchive.push({...c,schoolId:t.id,leftSeason:universe.year})}"
coach_block=r'''const COACH_SLOT_ROLES={HC:'Head Coach',OC:'Offensive Coordinator',DC:'Defensive Coordinator',RC:'Recruiting Coordinator',SC:'Strength & Performance'};
function coachSlot(t,c){return Object.entries(t?.staff||{}).find(([,x])=>x?.id===c?.id)?.[0]||Object.keys(COACH_SLOT_ROLES).find(k=>COACH_SLOT_ROLES[k]===c?.role)||null}
function coachSchemeIdentity(role,t){if(!t)return'Unknown';if(role==='Offensive Coordinator')return t.offScheme||'Unknown offense';if(role==='Defensive Coordinator')return t.defScheme||'Unknown defense';if(role==='Head Coach')return `${t.offScheme||'Unknown offense'} / ${t.defScheme||'Unknown defense'}`;if(role==='Recruiting Coordinator')return `${t.conference||'National'} recruiting`;return'Performance program'}
function coachSpecialties(c){const rows=[['Recruiting',c.recruiting],['Development',c.development],['Evaluation',c.evaluation],['Play calling',c.playCall],['Adaptability',c.adaptability]].sort((a,b)=>(b[1]||0)-(a[1]||0));return rows.slice(0,2).map(x=>`${x[0]} specialist`)}
function coachTraitText(c){let out=[];if((c.ambition||0)>=82)out.push('Highly ambitious');else if((c.ambition||0)<=45)out.push('Content in role');if((c.loyalty||0)>=82)out.push('Program loyalist');else if((c.loyalty||0)<=42)out.push('Open to movement');if((c.adaptability||0)>=84)out.push('Flexible tactician');return out.slice(0,2).join(' · ')||'Steady career profile'}
function coachById(id){if(!id)return null;for(const t of universe.teams||[])for(const [slot,c] of Object.entries(t.staff||{}))if(c?.id===id)return{coach:c,team:t,slot,active:true};const c=(universe.coachArchive||[]).find(x=>x.id===id);return c?{coach:c,team:null,slot:null,active:false}:null}
function ensureCoachCareer(c,t=null,slot=null){if(!c)return c;c.careerHistory??=[];c.seasons??=[];c.specialties=(c.specialties?.length?c.specialties:coachSpecialties(c));const role=COACH_SLOT_ROLES[slot]||c.role||'Coach',archived=c.status==='RETIRED'||c.status==='DEPARTED'||c.leftSeason!=null;if(t){c.schoolId=t.id;c.schoolName=t.name}c.status??=archived?'DEPARTED':'ACTIVE';if(!c.careerHistory.length){const end=archived?(c.leftSeason??universe.year):null,start=Math.max(2027,(end??universe.year)-Math.max(0,c.years||0));c.careerHistory.push({schoolId:c.schoolId??t?.id??null,schoolName:c.schoolName??t?.name??'Unknown',role,startSeason:start,endSeason:end,reasonEnded:archived?(c.departureReason||'Legacy departure'):null,scheme:coachSchemeIdentity(role,t),wins:0,losses:0,conferenceTitles:0,nationalTitles:0,awards:[],legacy:true})}if(t&&!archived){let cur=c.careerHistory.findLast?.(s=>s.endSeason==null)||c.careerHistory.slice().reverse().find(s=>s.endSeason==null);if(!cur){cur={schoolId:t.id,schoolName:t.name,role,startSeason:universe.year,endSeason:null,reasonEnded:null,scheme:coachSchemeIdentity(role,t),wins:0,losses:0,conferenceTitles:0,nationalTitles:0,awards:[]};c.careerHistory.push(cur)}c.status='ACTIVE';c.role=role;c.schoolId=t.id;c.schoolName=t.name}return c}
function normalizeCoachState(){promiseState();let used=new Set([...universe.teams.flatMap(t=>Object.values(t.staff||{})),...(universe.coachArchive||[])].map(c=>c?.id).filter(Boolean)),nextId=()=>{let id;do{id=`C${universe.nextCoachId++}`}while(used.has(id));used.add(id);return id};for(const t of universe.teams)for(const [slot,c] of Object.entries(t.staff||{})){if(!c.id)c.id=nextId();c.status='ACTIVE';delete c.leftSeason;delete c.departureReason;ensureCoachCareer(c,t,slot)}const active=new Set(universe.teams.flatMap(t=>Object.values(t.staff||{}).map(c=>c.id))),unique=new Map();for(const c of universe.coachArchive||[]){if(!c.id)c.id=nextId();if(active.has(c.id))continue;c.status=c.status==='RETIRED'?'RETIRED':'DEPARTED';const t=universe.teams.find(x=>x.id===c.schoolId)||universe.teams.find(x=>x.name===c.schoolName)||null;ensureCoachCareer(c,t,coachSlot(t,c));let cur=c.careerHistory?.find(s=>s.endSeason==null);if(cur){cur.endSeason=c.leftSeason??universe.year;cur.reasonEnded=c.departureReason||'Departed program'}unique.set(c.id,c)}universe.coachArchive=[...unique.values()]}
function recordCoachSeason(t){const year=universe.year,coy=(universe.awards?.[year]||[]).find(a=>a.name==='Coach of the Year')?.playerName;for(const [slot,c] of Object.entries(t.staff||{})){ensureCoachCareer(c,t,slot);if(c.seasons.some(s=>s.year===year&&s.schoolId===t.id&&s.role===c.role))continue;const row={year,schoolId:t.id,schoolName:t.name,role:c.role,scheme:coachSchemeIdentity(c.role,t),wins:t.w,losses:t.l,conferenceTitle:!!t.champ,nationalTitle:universe.champion===t.name,coachOfYear:slot==='HC'&&coy===c.name};c.seasons.push(row);const st=c.careerHistory.slice().reverse().find(s=>s.endSeason==null);if(st){st.wins=(st.wins||0)+t.w;st.losses=(st.losses||0)+t.l;st.conferenceTitles=(st.conferenceTitles||0)+(row.conferenceTitle?1:0);st.nationalTitles=(st.nationalTitles||0)+(row.nationalTitle?1:0);if(row.coachOfYear&&!st.awards.includes('Coach of the Year'))st.awards.push('Coach of the Year');st.scheme=row.scheme}}}
function closeCoachStint(c,t,endSeason=universe.year,reason='Departed program'){ensureCoachCareer(c,t,coachSlot(t,c));const st=c.careerHistory.slice().reverse().find(s=>s.endSeason==null);if(st){st.endSeason=Math.max(st.startSeason,endSeason);st.reasonEnded=reason}return st}
function openCoachStint(c,t,slot,startSeason=universe.year,reason='New job'){c.careerHistory??=[];const open=c.careerHistory.slice().reverse().find(s=>s.endSeason==null);if(open)closeCoachStint(c,t,startSeason-1,reason);c.role=COACH_SLOT_ROLES[slot]||c.role;c.schoolId=t.id;c.schoolName=t.name;c.status='ACTIVE';delete c.leftSeason;delete c.departureReason;c.careerHistory.push({schoolId:t.id,schoolName:t.name,role:c.role,startSeason,endSeason:null,reasonStarted:reason,reasonEnded:null,scheme:coachSchemeIdentity(c.role,t),wins:0,losses:0,conferenceTitles:0,nationalTitles:0,awards:[]});c.specialties=coachSpecialties(c);return c}
function archiveCoach(c,t,reason='Departed program',status='DEPARTED',endSeason=universe.year){if(!c)return null;ensureCoachCareer(c,t,coachSlot(t,c));closeCoachStint(c,t,endSeason,reason);c.status=status;c.leftSeason=endSeason;c.departureReason=reason;c.schoolId=t.id;c.schoolName=t.name;const copy=JSON.parse(JSON.stringify(c)),i=(universe.coachArchive||[]).findIndex(x=>x.id===c.id);if(i>=0)universe.coachArchive[i]=copy;else universe.coachArchive.push(copy);return copy}
function rememberCoach(c,t){promiseState();ensureCoachCareer(c,t,coachSlot(t,c));if(!universe.coachArchive.some(x=>x.id===c.id))universe.coachArchive.push({...JSON.parse(JSON.stringify(c)),schoolId:t.id,schoolName:t.name,leftSeason:universe.year})}
function addCoachEvent(type,c,fromTeam=null,toTeam=null,metadata={},summary=null){promiseState();const order=universe.nextEventId++,schools=[...new Set([fromTeam?.id,toTeam?.id].filter(x=>x!=null))],e={id:`EVT_${order}`,season:universe.year,week:universe.week,timestampOrder:order,type,importance:['COACH_FIRED','COACH_RETIRED','COACH_MOVED','COACH_PROMOTED'].includes(type)?65:45,schoolIds:schools,playerIds:[],coachIds:[c.id],recruitIds:[],gameIds:[],summary:summary||`${c.name}: ${type.replaceAll('_',' ').toLowerCase()}.`,metadata};universe.events.push(e);return e}
function startGeneratedCoach(t,slot,startSeason=universe.year+1,reason='Staff replacement'){const c=generateCoach(COACH_SLOT_ROLES[slot],t,0);openCoachStint(c,t,slot,startSeason,reason);return c}
function replaceStaffCoach(t,slot,reason='Staff change',status='DEPARTED',startSeason=universe.year+1){const old=t.staff[slot];archiveCoach(old,t,reason,status,universe.year);const fresh=startGeneratedCoach(t,slot,startSeason,reason);t.staff[slot]=fresh;const type=status==='RETIRED'?'COACH_RETIRED':status==='FIRED'?'COACH_FIRED':'COACH_DEPARTED';addCoachEvent(type,old,t,null,{role:old.role,replacementCoachId:fresh.id,reason},`${old.name} ${status==='FIRED'?'was fired by':status==='RETIRED'?'retired from':'left'} ${t.name}; ${fresh.name} takes over as ${fresh.role}.`);return{old,fresh}}
function promoteCoachWithinTeam(t,fromSlot,toSlot='HC',reason='Internal promotion',displacedStatus='DEPARTED'){const promoted=t.staff[fromSlot],displaced=t.staff[toSlot],next=universe.year+1;archiveCoach(displaced,t,reason,displacedStatus,universe.year);addCoachEvent(displacedStatus==='RETIRED'?'COACH_RETIRED':displacedStatus==='FIRED'?'COACH_FIRED':'COACH_DEPARTED',displaced,t,null,{role:displaced.role,reason});closeCoachStint(promoted,t,universe.year,'Promoted internally');t.staff[toSlot]=promoted;openCoachStint(promoted,t,toSlot,next,reason);t.staff[fromSlot]=startGeneratedCoach(t,fromSlot,next,'Vacancy after internal promotion');addCoachEvent('COACH_PROMOTED',promoted,t,t,{fromRole:COACH_SLOT_ROLES[fromSlot],toRole:COACH_SLOT_ROLES[toSlot],reason},`${promoted.name} promoted from ${COACH_SLOT_ROLES[fromSlot]} to ${COACH_SLOT_ROLES[toSlot]} at ${t.name}.`);return promoted}
function moveCoach(c,from,to,toSlot,reason='Accepted new job'){const fromSlot=coachSlot(from,c);if(!fromSlot||!to?.staff?.[toSlot])return null;const displaced=to.staff[toSlot],next=universe.year+1;archiveCoach(displaced,to,`Replaced by ${c.name}`,'DEPARTED',universe.year);addCoachEvent('COACH_DEPARTED',displaced,to,null,{role:displaced.role,reason:'Replaced'});closeCoachStint(c,from,universe.year,reason);from.staff[fromSlot]=startGeneratedCoach(from,fromSlot,next,'Vacancy after coach departure');to.staff[toSlot]=c;openCoachStint(c,to,toSlot,next,reason);addCoachEvent('COACH_MOVED',c,from,to,{fromRole:COACH_SLOT_ROLES[fromSlot],toRole:COACH_SLOT_ROLES[toSlot],reason},`${c.name}: ${from.name} ${COACH_SLOT_ROLES[fromSlot]} → ${to.name} ${COACH_SLOT_ROLES[toSlot]}.`);return c}
function retireCoach(t,slot,reason='Retired from coaching'){const c=t.staff[slot];replaceStaffCoach(t,slot,reason,'RETIRED',universe.year+1);return c}
function coachRetirementChance(c){const a=c?.age||0;return a>=72?.18:a>=68?.07:a>=65?.025:0}
function coachCareerTotals(c){const seasons=c.seasons||[];return{wins:seasons.reduce((n,s)=>n+(s.wins||0),0),losses:seasons.reduce((n,s)=>n+(s.losses||0),0),conferenceTitles:seasons.filter(s=>s.conferenceTitle).length,nationalTitles:seasons.filter(s=>s.nationalTitle).length,coachAwards:seasons.filter(s=>s.coachOfYear).length,seasons:seasons.length}}
const coachEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function coachProfileHTML(c){const totals=coachCareerTotals(c),stints=(c.careerHistory||[]).slice().reverse(),seasons=(c.seasons||[]).slice().reverse().slice(0,12);return `<div class="profile-grid"><div class="profile-stat"><div class="small muted">Career record</div><div class="v">${totals.wins}–${totals.losses}</div></div><div class="profile-stat"><div class="small muted">Seasons tracked</div><div class="v">${totals.seasons}</div></div><div class="profile-stat"><div class="small muted">Conference titles</div><div class="v">${totals.conferenceTitles}</div></div><div class="profile-stat"><div class="small muted">National titles</div><div class="v">${totals.nationalTitles}</div></div></div><div class="two-col"><div><h3>Career profile</h3><div class="lineitem"><span>Specialties</span><strong>${coachEscape((c.specialties||coachSpecialties(c)).join(' · '))}</strong></div><div class="lineitem"><span>Career traits</span><strong>${coachEscape(coachTraitText(c))}</strong></div><div class="lineitem"><span>Coach of the Year</span><strong>${totals.coachAwards}</strong></div></div><div><h3>Recent seasons</h3>${seasons.length?seasons.map(s=>`<div class="lineitem"><span>${s.year} · ${coachEscape(s.schoolName)} · ${coachEscape(s.role)}</span><strong>${s.wins}–${s.losses}${s.nationalTitle?' · National title':s.conferenceTitle?' · Conf title':''}</strong></div>`).join(''):'<div class="muted">No completed seasons tracked yet.</div>'}</div></div><h3 style="margin-top:14px">Career timeline</h3><div class="timeline">${stints.map(s=>`<div class="timeline-row"><strong>${coachEscape(s.startSeason)}${s.endSeason?`–${coachEscape(s.endSeason)}`:'–present'} · ${coachEscape(s.schoolName)} · ${coachEscape(s.role)}</strong><div>${s.wins||0}–${s.losses||0}${s.nationalTitles?` · ${s.nationalTitles} national title${s.nationalTitles===1?'':'s'}`:''}${s.conferenceTitles?` · ${s.conferenceTitles} conference title${s.conferenceTitles===1?'':'s'}`:''}</div><div class="small muted">${coachEscape(s.scheme||'Scheme not recorded')}${s.reasonEnded?` · ${coachEscape(s.reasonEnded)}`:''}${s.legacy?' · legacy tenure begins at dynasty start':''}</div></div>`).join('')}</div>`}
function showCoachProfile(id){const found=coachById(id);if(!found)return;const c=found.coach,t=found.team;$('#coachDialogName').textContent=c.name;$('#coachDialogMeta').textContent=`Age ${c.age} · ${c.role} · ${found.active?(t?.name||c.schoolName):c.status==='RETIRED'?'Retired':`Formerly ${c.schoolName||'in the dynasty'}`}`;$('#coachDialogBody').innerHTML=coachProfileHTML(c);const d=$('#coachDialog');if(d.showModal)d.showModal();else d.setAttribute('open','')}
function renderCoachHistory(t){const current=new Set(Object.values(t.staff||{}).map(c=>c.id)),rows=(universe.coachArchive||[]).filter(c=>!current.has(c.id)&&(c.careerHistory||[]).some(s=>s.schoolId===t.id)).sort((a,b)=>Math.max(...(b.careerHistory||[]).map(s=>s.endSeason||9999))-Math.max(...(a.careerHistory||[]).map(s=>s.endSeason||9999))).slice(0,12);$('#coachHistoryList').innerHTML=rows.length?rows.map(c=>{const last=(c.careerHistory||[]).filter(s=>s.schoolId===t.id).at(-1),tot=coachCareerTotals(c);return `<div class="lineitem"><span><button class="player-button" data-coach="${coachEscape(c.id)}">${coachEscape(c.name)}</button> · ${coachEscape(last?.role||c.role)}</span><span>${tot.wins}–${tot.losses} career · ${coachEscape(c.status||'Departed')}</span></div>`}).join(''):'<span class="muted">Former coaches will appear as the carousel develops.</span>'}
function attachCoachLinks(){$$('[data-coach]').forEach(b=>{const open=()=>showCoachProfile(b.dataset.coach);b.onclick=open;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}})}'''
app=must_replace(app,old,coach_block,'coach helper block')

# Make generated coaches career-ready without changing the existing rating model.
pattern=r"function generateCoach\(role,school\)\{\n const base=56\+school\.prestige\*\.16\+school\.resources\*\.08;\n return \{id:uid\(\),name:`\$\{pick\(FIRST\)\} \$\{pick\(LAST\)\}`,role,age:gi\(31,66\),recruiting:staffRating\(base\),development:staffRating\(base\),evaluation:staffRating\(base\),playCall:staffRating\(base\),adaptability:staffRating\(base\),loyalty:staffRating\(63\),ambition:staffRating\(68\),years:gi\(0,6\),contractYears:gi\(2,5\),salary:Math\.round\(\(0\.35\+school\.resources/35\+school\.prestige/45\+\(role==='Head Coach'\?2\.4:role\.includes\('Coordinator'\)\?0\.9:0\)\)\*10\)/10\};\n\}"
replacement="""function generateCoach(role,school,tenure=null){\n const base=56+school.prestige*.16+school.resources*.08;\n const c={id:uid(),name:`${pick(FIRST)} ${pick(LAST)}`,role,age:gi(31,66),recruiting:staffRating(base),development:staffRating(base),evaluation:staffRating(base),playCall:staffRating(base),adaptability:staffRating(base),loyalty:staffRating(63),ambition:staffRating(68),years:tenure==null?gi(0,6):tenure,contractYears:gi(2,5),salary:Math.round((0.35+school.resources/35+school.prestige/45+(role==='Head Coach'?2.4:role.includes('Coordinator')?0.9:0))*10)/10,schoolId:school.id,schoolName:school.name,status:'ACTIVE',careerHistory:[],seasons:[]};\n c.specialties=coachSpecialties(c);return c;\n}"""
app,n=re.subn(pattern,replacement,app,count=1)
if n!=1: raise SystemExit('generateCoach patch failed')

# Normalize durable coach careers after the existing promise/ID migration.
anchor=" for(const e of universe.events){const pr=/^PR_(\\d+)$/.exec(e.metadata?.promiseId);if(pr)universe.nextPromiseId=Math.max(universe.nextPromiseId,+pr[1]+1);const n=/^EVT_(\\d+)$/.exec(e.id);if(n)universe.nextEventId=Math.max(universe.nextEventId,+n[1]+1)}\n}"
repl=" for(const e of universe.events){const pr=/^PR_(\\d+)$/.exec(e.metadata?.promiseId);if(pr)universe.nextPromiseId=Math.max(universe.nextPromiseId,+pr[1]+1);const n=/^EVT_(\\d+)$/.exec(e.id);if(n)universe.nextEventId=Math.max(universe.nextEventId,+n[1]+1)}\n normalizeCoachState();\n}"
app=must_replace(app,anchor,repl,'normalizeCoachState call')

# Replace the old opaque carousel with career-aware turnover, retirement and bounded internal promotion.
carousel_pattern=r"function carousel\(\)\{.*?\}\nfunction runOffseason\(\)"
carousel_new=r'''function carousel(){let log=[];for(const t of universe.teams){recordCoachSeason(t);for(const c of Object.values(t.staff)){c.age=(c.age||40)+1;c.years=(c.years||0)+1;c.contractYears=Math.max(0,(c.contractYears??2)-1)}const changed=new Set(),next=universe.year+1,hc=t.staff.HC,expected=clamp(Math.round((t.prestige-30)/8),4,10),bad=t.w<expected-2,fire=bad&&Math.random()>(t.admin_patience/100),hcRetire=Math.random()<coachRetirementChance(hc);if(fire||hcRetire){const status=hcRetire?'RETIRED':'FIRED',reason=hcRetire?'Retired after the season':`Fired after ${t.w}-${t.l}`;let candidates=['OC','DC'].map(slot=>({slot,c:t.staff[slot],score:(t.staff[slot].ambition||60)+(t.staff[slot].playCall||60)*.35+(t.staff[slot].development||60)*.2})).sort((a,b)=>b.score-a.score),promote=Math.random()<.32&&candidates[0]?.c;if(promote){const who=candidates[0],oldName=hc.name;promoteCoachWithinTeam(t,who.slot,'HC',reason,status);changed.add('HC');changed.add(who.slot);log.push(`${t.name}: ${oldName} ${status==='FIRED'?'was fired':'retired'}; ${who.c.name} promoted from ${COACH_SLOT_ROLES[who.slot]} to Head Coach.`)}else{const x=replaceStaffCoach(t,'HC',reason,status,next);changed.add('HC');log.push(`${t.name}: ${x.old.name} ${status==='FIRED'?'was fired':'retired'}; ${x.fresh.name} hired as Head Coach.`)}}for(const slot of ['OC','DC']){if(changed.has(slot))continue;const c=t.staff[slot],retire=Math.random()<coachRetirementChance(c),turn=!retire&&Math.random()<(slot==='OC'?.07+c.ambition/900:.06+c.ambition/1000);if(retire||turn){const x=replaceStaffCoach(t,slot,retire?'Retired after the season':'Left for another opportunity',retire?'RETIRED':'DEPARTED',next);changed.add(slot);log.push(`${t.name}: ${x.old.name} ${retire?'retired':`left as ${COACH_SLOT_ROLES[slot]}`}; ${x.fresh.name} takes over.`)}}for(const slot of ['RC','SC']){if(changed.has(slot))continue;const c=t.staff[slot];if(Math.random()<coachRetirementChance(c)){const x=replaceStaffCoach(t,slot,'Retired after the season','RETIRED',next);log.push(`${t.name}: ${x.old.name} retired; ${x.fresh.name} takes over as ${COACH_SLOT_ROLES[slot]}.`)}}}return log}
function runOffseason()'''
app,n=re.subn(carousel_pattern,carousel_new,app,count=1,flags=re.S)
if n!=1: raise SystemExit('carousel patch failed')

# Staff cards now open coach profiles and include historical staff from the selected school.
render_pattern=r"function renderStaff\(\)\{.*?\}\nfunction renderGameLab\(\)"
render_new=r'''function renderStaff(){const u=selected();$('#staffList').innerHTML=Object.values(u.staff).map(c=>{ensureCoachCareer(c,u,coachSlot(u,c));return `<div class="coach-card"><div class="strong"><button class="player-button" data-coach="${coachEscape(c.id)}">${coachEscape(c.name)}</button> <span class="pill">${coachEscape(c.role)}</span></div><div class="compact muted">Age ${c.age} · Year ${c.years+1} · ${c.contractYears??2} yr contract · $${c.salary??1.2}M</div><div class="compact">Recruit ${grade(c.recruiting)} · Develop ${grade(c.development)} · Evaluate ${grade(c.evaluation)} · Call ${grade(c.playCall)} · Adapt ${grade(c.adaptability)}</div><div class="small muted">${coachEscape((c.specialties||coachSpecialties(c)).join(' · '))} · ${coachEscape(coachTraitText(c))}</div></div>`}).join('');const o=OFF_SCHEMES[u.offScheme],d=DEF_SCHEMES[u.defScheme];$('#schemeCard').innerHTML=`<div class="scheme-badge">OFF: ${u.offScheme}</div><div class="compact muted">Pass tendency ${Math.round(o.pass*100)}% · Pace ${o.pace}/100 · Core traits: ${o.traits.join(', ')}</div><br><div class="scheme-badge">DEF: ${u.defScheme}</div><div class="compact muted">Pressure ${d.pressure} · Coverage ${d.coverage} · Run control ${d.run} · Core traits: ${d.traits.join(', ')}</div>`;$('#schemeFitLeaders').innerHTML=u.roster.slice().sort((a,b)=>playerSchemeFit(b,u)-playerSchemeFit(a,u)).slice(0,10).map(p=>`<div class="lineitem"><span>${p.pos} ${p.name} · ${p.style}</span><strong>${grade(playerSchemeFit(p,u))} (${playerSchemeFit(p,u)})</strong></div>`).join('');renderCoachHistory(u);attachCoachLinks()}
function renderGameLab()'''
app,n=re.subn(render_pattern,render_new,app,count=1,flags=re.S)
if n!=1: raise SystemExit('renderStaff patch failed')

